/* k10_prefix: inclusive prefix sum, out[i] = x[0] + ... + x[i].
 * LOOP-CARRIED DEPENDENCY: each step needs the previous one. A plain
 * "parallel for" gives wrong answers; a correct version needs a two-pass
 * block scan (or OpenMP 5's scan directive). Integer data keeps it exact. */
#include "common.h"
#include <omp.h>

/* === KERNEL BEGIN === */
static void kernel(long n, int reps, const long *x, long *out) {
    for (int r = 0; r < reps; r++) {
        long run = 0;
        /* OpenMP 5.0+ inclusive scan directive allows efficient parallelization 
           of prefix sums. The 'inscan' reduction tells the compiler that 
           the variable 'run' will be used in a scan operation within the loop. */
        #pragma omp parallel for reduction(inscan, +:run)
        for (long i = 0; i < n; i++) {
            run += x[i];
            #pragma omp scan inclusive(run)
            out[i] = run;
        }
    }
}
/* === KERNEL END === */

